:root {
  color-scheme: dark;
  font-family: system-ui, -apple-system, Segoe UI, sans-serif;
  font-size: 16px;
  background: #18252b;
  color: #f7f1df;
  --panel: #24383d;
  --panel-light: #30484b;
  --cream: #f7f1df;
  --lime: #c8f36a;
  --orange: #ff9f5b;
  --muted: #b6c6b9;
}
* { box-sizing: border-box; }
[hidden] { display: none !important; }
body {
  min-height: 100vh; margin: 0; padding: 32px 16px;
  display: grid; place-items: center;
  background-color: #18252b;
  background-image: linear-gradient(90deg, #24383d 1px, transparent 1px), linear-gradient(#24383d 1px, transparent 1px);
  background-size: 32px 32px;
}
button { font: inherit; }
.board {
  width: min(100%, 960px); padding: clamp(20px, 4vw, 36px);
  background: var(--panel); border: 4px solid var(--cream);
  box-shadow: 8px 8px 0 #10191d; 
}
.topbar { display: flex; align-items: center; justify-content: space-between; gap: 18px; margin-bottom: 30px; }
.eyebrow { margin: 0 0 8px; color: var(--lime); font-size: .8rem; font-weight: 800; letter-spacing: .14em; }
h1 { margin: 0; font-size: clamp(1.8rem, 6vw, 3rem); line-height: 1.05; letter-spacing: -.04em; }
.score-badge { min-width: 116px; padding: 12px 16px; text-align: center; color: #18252b; background: var(--lime); border: 3px solid var(--cream); box-shadow: 4px 4px 0 #10191d; }
.score-badge span { display: block; font-size: .7rem; font-weight: 900; letter-spacing: .1em; }
.score-badge strong { display: block; margin-top: 3px; font-size: 2rem; line-height: 1.1; }
.section-heading { display: flex; justify-content: space-between; align-items: baseline; gap: 12px; margin-bottom: 12px; }
h2 { margin: 0; font-size: 1.1rem; }
.section-heading p, .entry-hint { margin: 0; color: var(--muted); font-size: .9rem; }
.frames-wrap { overflow-x: auto; padding: 0 0 8px; }
.score-sheet { width: 100%; min-width: 620px; table-layout: fixed; border-collapse: separate; border-spacing: 3px; }
.score-sheet th, .score-sheet td { text-align: center; }
.score-sheet th { height: 38px; color: var(--muted); font-size: .75rem; font-weight: 800; }
.score-sheet td { background: var(--panel-light); }
.score-sheet td:first-child, .score-sheet th:first-child { border-left: 0; }
.roll-row td { height: 72px; padding: 5px; vertical-align: top; }
.rolls { display: flex; justify-content: flex-end; gap: 3px; min-height: 28px; }
.roll { display: grid; place-items: center; width: 28px; height: 28px; background: #18252b; border: 1px solid #61736a; font-weight: 800; }
.roll.mark { color: var(--lime); }
.total-row td { height: 42px; color: var(--lime); font-size: 1.2rem; font-weight: 900; }
.total-row td.pending { color: #80938a; }
.entry { margin-top: 28px; padding-top: 22px; border-top: 2px solid #45605c; }
.pin-buttons { display: grid; grid-template-columns: repeat(11, minmax(34px, 1fr)); gap: 8px; }
.pin-button { min-height: 48px; padding: 6px 2px; color: var(--cream); background: #18252b; border: 2px solid #81918a; font-size: 1rem; font-weight: 800; cursor: pointer; transition: transform .08s, background .12s, color .12s; }
.pin-button:hover:not(:disabled) { color: #18252b; background: var(--lime); border-color: var(--lime); }
.pin-button:active:not(:disabled) { transform: translate(2px, 2px); }
button:focus-visible { outline: 3px solid var(--orange); outline-offset: 3px; }
.pin-button:disabled { opacity: .35; cursor: not-allowed; }
.actions { display: flex; justify-content: space-between; gap: 12px; margin-top: 16px; }
.secondary { padding: 9px 12px; color: var(--cream); background: transparent; border: 2px solid #81918a; cursor: pointer; }
.secondary:hover:not(:disabled) { color: #18252b; background: var(--orange); border-color: var(--orange); }
.secondary:active:not(:disabled) { transform: translateY(2px); }
.secondary:disabled { opacity: .4; cursor: not-allowed; }
footer { margin-top: 26px; color: var(--muted); font-size: .72rem; font-weight: 800; letter-spacing: .07em; text-align: center; }
footer b { color: var(--lime); font-size: .95rem; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }
@media (max-width: 560px) {
  body { padding: 16px 10px; }
  .board { padding: 20px 14px; border-width: 3px; }
  .topbar { align-items: flex-start; }
  .score-badge { min-width: 92px; padding: 9px 10px; }
  .score-badge strong { font-size: 1.7rem; }
  .section-heading { align-items: flex-start; flex-direction: column; gap: 5px; }
  .pin-buttons { grid-template-columns: repeat(6, 1fr); }
  .pin-button:last-child { grid-column: span 2; }
}

const head = document.getElementById('frame-head');
const rollsRow = document.getElementById('roll-row');
const totalRow = document.getElementById('total-row');
const buttonsBox = document.getElementById('pin-buttons');
const status = document.getElementById('status');
const undoButton = document.getElementById('undo');
const finalScore = document.getElementById('final-score');
let rolls = [];

for (let frame = 1; frame <= 10; frame++) {
  const th = document.createElement('th');
  th.scope = 'col'; th.textContent = `F${frame}`;
  head.append(th);
  rollsRow.append(document.createElement('td'));
  totalRow.append(document.createElement('td'));
}

for (let pins = 0; pins <= 10; pins++) {
  const button = document.createElement('button');
  button.type = 'button'; button.className = 'pin-button'; button.textContent = String(pins);
  button.setAttribute('aria-label', `${pins} ${pins === 1 ? 'pin' : 'pins'}`);
  button.addEventListener('click', () => addRoll(pins));
  buttonsBox.append(button);
}

function frameRolls() {
  const frames = [];
  let index = 0;
  for (let frame = 0; frame < 10 && index < rolls.length; frame++) {
    const first = rolls[index++];
    if (frame < 9 && first === 10) frames.push([first]);
    else if (frame < 9) {
      if (index < rolls.length) frames.push([first, rolls[index++]]);
      else frames.push([first]);
    } else {
      const last = [first];
      if (index < rolls.length) last.push(rolls[index++]);
      if (last.length === 2 && (first === 10 || first + last[1] === 10) && index < rolls.length) last.push(rolls[index++]);
      frames.push(last);
    }
  }
  return frames;
}

function scoreFrames(frames) {
  const result = [];
  let cursor = 0, total = 0;
  for (let frame = 0; frame < frames.length; frame++) {
    const current = frames[frame];
    if (frame === 9) {
      if (current.length === 3 || (current.length === 2 && current[0] !== 10 && current[0] + current[1] < 10)) {
        total += current.reduce((sum, pins) => sum + pins, 0);
        result.push(total);
      } else result.push(null);
      continue;
    }
    if (!current.length) { result.push(null); continue; }
    if (current[0] === 10) {
      if (rolls.length - cursor < 3) { result.push(null); cursor++; continue; }
      total += 10 + rolls[cursor + 1] + rolls[cursor + 2];
      result.push(total); cursor++;
    } else if (current.length < 2) { result.push(null); cursor++; }
    else if (current[0] + current[1] === 10) {
      if (rolls.length - cursor < 3) { result.push(null); cursor += 2; continue; }
      total += 10 + rolls[cursor + 2]; result.push(total); cursor += 2;
    } else {
      total += current[0] + current[1]; result.push(total); cursor += 2;
    }
  }
  return result;
}

function displayRolls(frames) {
  return frames.map((frame, frameIndex) => {
    if (frameIndex < 9 && frame.length === 1 && frame[0] === 10) return ['X'];
    return frame.map((pins, rollIndex) => {
      if (frameIndex === 9) {
        if (rollIndex > 0 && frame[rollIndex - 1] !== 10 && frame[rollIndex - 1] + pins === 10) return '/';
        return pins === 10 ? 'X' : String(pins);
      }
      if (rollIndex === 1 && frame[0] + pins === 10) return '/';
      return String(pins);
    });
  });
}

function validNext(pins) {
  const frames = frameRolls();
  if (frames.length >= 10 && frames[9].length >= 3) return false;
  if (frames.length === 10) {
    const tenth = frames[9];
    if (tenth.length === 1) return tenth[0] === 10 || pins <= 10 - tenth[0];
    if (tenth.length === 2) {
      if (tenth[0] === 10 && tenth[1] < 10) return pins <= 10 - tenth[1];
      if (tenth[0] === 10 || tenth[0] + tenth[1] === 10) return true;
      return false;
    }
  }
  if (!rolls.length) return true;
  const previousFrames = frames;
  const current = previousFrames[previousFrames.length - 1];
  if (current.length === 1 && current[0] !== 10) return pins <= 10 - current[0];
  return true;
}

function addRoll(pins) {
  if (!validNext(pins)) return;
  rolls.push(pins);
  render();
}

function render() {
  const frames = frameRolls();
  const totals = scoreFrames(frames);
  const marks = displayRolls(frames);
  [...rollsRow.children].forEach((cell, index) => {
    cell.replaceChildren();
    const line = document.createElement('div'); line.className = 'rolls';
    (marks[index] || []).forEach(mark => {
      const span = document.createElement('span'); span.className = `roll${mark === 'X' || mark === '/' ? ' mark' : ''}`;
      span.textContent = mark; line.append(span);
    });
    cell.append(line);
  });
  [...totalRow.children].forEach((cell, index) => {
    const value = totals[index]; cell.textContent = value == null ? '·' : String(value);
    cell.classList.toggle('pending', value == null);
  });
  const done = frames.length === 10 && frames[9].length === 3;
  finalScore.textContent = done ? String(totals[9]) : '—';
  undoButton.disabled = rolls.length === 0;
  const max = nextMaximum();
  [...buttonsBox.children].forEach((button, pins) => { button.disabled = done || pins > max; });
  status.textContent = done ? 'Game complete. Nice game!' : `Roll ${rolls.length + 1} · choose up to ${max} pin${max === 1 ? '' : 's'}.`;
}

function nextMaximum() {
  const frames = frameRolls();
  if (frames.length === 10) {
    const frame = frames[9];
    if (frame.length === 1) return frame[0] === 10 ? 10 : 10 - frame[0];
    if (frame.length === 2 && (frame[0] === 10 || frame[0] + frame[1] === 10)) {
      if (frame[0] === 10 && frame[1] < 10) return 10 - frame[1];
      return 10;
    }
    return 0;
  }
  if (frames.length && frames.at(-1).length === 1 && frames.at(-1)[0] !== 10) return 10 - frames.at(-1)[0];
  return 10;
}

undoButton.addEventListener('click', () => { rolls.pop(); render(); });
document.getElementById('reset').addEventListener('click', () => { rolls = []; render(); });
document.addEventListener('keydown', event => {
  if (event.altKey || event.ctrlKey || event.metaKey) return;
  if (/^[0-9]$/.test(event.key) && !event.repeat) {
    const value = Number(event.key);
    if (value <= nextMaximum()) addRoll(value);
  } else if (event.key === 'Backspace' && rolls.length) {
    event.preventDefault(); rolls.pop(); render();
  }
});
render();
